'use strict';
const steps=[['start','Start here'],['model','Explore the model'],['excel','Build in Excel'],['solve','Solve both problems'],['sensitivity','Interpret the reports'],['submit','Check & submit']];
const key='f422-lab7-v1';
let state={done:[],checks:[],notes:['',''],stock:[120,20,6,2],harvest:[20,0,0,0]};
let storageOK=true;
try{const s=JSON.parse(localStorage.getItem(key));if(s&&typeof s==='object'){if(Array.isArray(s.done))state.done=s.done.filter(x=>Number.isInteger(x)&&x>=0&&x<6);if(Array.isArray(s.checks))state.checks=s.checks.filter(x=>Number.isInteger(x)&&x>=0&&x<8);if(Array.isArray(s.notes))state.notes=[0,1].map(i=>typeof s.notes[i]==='string'?s.notes[i]:'');for(const k of ['stock','harvest'])if(Array.isArray(s[k])&&s[k].length===4&&s[k].every(n=>Number.isFinite(n)&&n>=0))state[k]=s[k];}}catch{storageOK=false;}
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{storageOK=false;}if(!storageOK)document.querySelector('#save-status').textContent='Browser storage is unavailable. Export your notes before leaving.';};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formulas=[['D5','=100+0.61*(B5-B12)-0.4*(B6-B13)-1.4*(B7-B14)-2.4*(B8-B15)','Next-period class 1'],['D6','=0.04*(B5-B12)+0.8*(B6-B13)','Next-period class 2'],['D7','=0.06*(B6-B13)+0.8*(B7-B14)','Next-period class 3'],['D8','=0.04*(B7-B14)+0.9*(B8-B15)','Next-period class 4'],['E8','=D7+D8','Large trees (trees/ha)'],['C16','=SUMPRODUCT(B12:B15,C12:C15)','Harvest (m³/ha/5 years)']];
const heading=(n,title,desc)=>`<p class="eyebrow">LAB 07 / STEP 0${n+1}</p><h1>${title}</h1><p class="intro">${desc}</p>`;
const quiz=(id,title,options,answer,explanation)=>`<div class="panel quiz" data-answer="${answer}" data-explanation="${esc(explanation)}"><h3>${title}</h3>${options.map((o,i)=>`<label><input type="radio" name="${id}" value="${i}">${o}</label>`).join('')}<button class="check-answer" style="margin-top:16px">Check understanding</button><div class="feedback" aria-live="polite"></div></div>`;
const forest=`<svg class="forest" viewBox="0 0 340 230" role="img" aria-label="Four increasing tree size classes, from small trees to large trees"><path d="M10 205 Q170 185 330 205" fill="none" stroke="#a4b496"/><g fill="#6c865e"><path d="M47 120 21 177H73Z"/><path d="M111 80 73 169H149Z"/></g><g fill="#315d47"><path d="M195 39 143 158H247Z"/><path d="M280 5 222 149H338Z"/></g><g stroke="#8e7750" stroke-width="6"><path d="M47 168V201M111 154V200M195 135V199M280 123V200"/></g><g fill="#315d47" font-size="11" text-anchor="middle"><text x="47" y="224">CLASS 1</text><text x="111" y="224">CLASS 2</text><text x="195" y="224">CLASS 3</text><text x="280" y="224">CLASS 4</text></g></svg>`;
const pages=[
()=>`<div class="hero"><div>${heading(0,'A forest in balance.','Learn how to balance large-tree retention and timber production in an uneven-aged forest. Follow this guide alongside Excel to complete Lab 7 independently.')}<a class="button-link" href="#model">Begin the walkthrough →</a></div><div class="hero-art">${forest}<small>FOUR SIZE CLASSES · ONE REPEATING CYCLE</small></div></div><div class="facts"><div><strong>5 years</strong><small>per cutting cycle</small></div><div><strong>2 objectives</strong><small>two separate LP models</small></div><div><strong>4 worksheets</strong><small>one Excel submission</small></div></div><div class="two-col"><section><h2>What you’ll learn</h2><ul><li>Translate stock, harvest, and growth into a linear program.</li><li>Maintain a steady state across five-year cutting cycles.</li><li>Compare two management objectives using Solver.</li><li>Explain the opportunity cost shown by a shadow price.</li></ul></section><section><h2>Before you begin</h2><p>Have desktop Excel with the Solver add-in and a new workbook ready. Keep the lab handout nearby. The handout refers to textbook problems 8.7 (p. 152) and 8.10 (p. 153).</p><p class="small">This guide contains the supplied equations and assignment requirements, so the setup is explained here.</p></section></div><div class="actions"><a class="button-link" download href="downloads/Lab7_Uneven_Aged.docx">Download lab handout ↓</a><a class="button-link" href="https://support.microsoft.com/en-au/excel/load-the-solver-add-in-in-excel" target="_blank" rel="noopener">Enable Solver ↗</a></div><div class="callout"><strong>Your deliverable:</strong> submit one Excel file with <code>max_large_trees</code>, <code>report_large_trees</code>, <code>max_timber</code>, and <code>report_timber</code>. Write the two shadow-price explanations inside the workbook. Follow your course’s submission location and deadline.</div><h2>Work at your own pace</h2><p>Use the six steps on the left, try the practice checks, and mark each step complete. Progress and reflection notes are saved only in this browser when storage is available. This site does not send work to your instructor.</p>`,
()=>`${heading(1,'Stock. Harvest. Regrow.','A steady-state forest returns to the same size-class distribution after every five-year cutting cycle. The individual trees can change; the class totals repeat.')}<div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Meaning</th><th>Unit</th></tr></thead><tbody><tr><td><i>y</i><sub>i,t</sub></td><td>Stock in size class i before harvest at time t</td><td>trees/ha</td></tr><tr><td><i>h</i><sub>i,t</sub></td><td>Trees removed from class i during the cycle</td><td>trees/ha/cycle</td></tr><tr><td><i>y</i><sub>i,t</sub> − <i>h</i><sub>i,t</sub></td><td>Residual trees that feed the growth equations</td><td>trees/ha</td></tr><tr><td><i>y</i><sub>i,t+1</sub></td><td>Stock five years later, calculated from residual trees</td><td>trees/ha</td></tr></tbody></table></div><p>Use <strong>size (diameter) classes</strong> 1–4, with classes 3 and 4 counted as large trees. Let <strong>r<sub>i</sub> = y<sub>i,t</sub> − h<sub>i,t</sub></strong> to read the equations below.</p><div class="equations"><div>y₁,t+1 = 100 + 0.61r₁ − 0.40r₂ − 1.40r₃ − 2.40r₄</div><div>y₂,t+1 = 0.04r₁ + 0.80r₂</div><div>y₃,t+1 = 0.06r₂ + 0.80r₃</div><div>y₄,t+1 = 0.04r₃ + 0.90r₄</div></div><p class="small">These are the handout’s equations (2)–(5). Keep the negative terms and the +100 in the first equation. All four steady-state equalities require y<sub>i,t+1</sub> = y<sub>i,t</sub>. Harvest cannot exceed stock, and all stock and harvest variables must be nonnegative.</p><section class="panel"><p class="eyebrow">TRY IT / ONE-CYCLE EXPLORER</p><h2>Does your forest return to itself?</h2><p class="small">Edit stock and harvest, then compare the projected state. Starting values are a practice scenario, not an optimal solution. This panel checks feasibility; it does not optimize.</p><div class="table-wrap"><table><thead><tr><th>Class</th><th>Stock y<sub>t</sub></th><th>Harvest h<sub>t</sub></th><th>Next y<sub>t+1</sub></th><th>Change</th></tr></thead><tbody>${[0,1,2,3].map(i=>`<tr><td>${i+1}</td><td><input type="number" min="0" step="any" value="${state.stock[i]}" data-stock="${i}" aria-label="Class ${i+1} stock in trees per hectare"></td><td><input type="number" min="0" step="any" value="${state.harvest[i]}" data-harvest="${i}" aria-label="Class ${i+1} harvest in trees per hectare"></td><td id="projection-${i}"></td><td id="change-${i}"></td></tr>`).join('')}</tbody></table></div><div class="metric-row"><div class="metric"><strong id="large-output">—</strong><small>large trees/ha next cycle</small></div><div class="metric"><strong id="harvest-output">—</strong><small>m³ harvested/ha/5 years</small></div><div class="metric"><strong id="drift-output">—</strong><small>largest class change (trees/ha)</small></div></div><div id="model-feedback" class="feedback" aria-live="polite"></div><div class="legend"><span>Current stock</span><span>Next-period stock</span></div><svg id="chart" class="chart" viewBox="0 0 650 240" role="img" aria-label="Current and projected tree stock by size class"></svg><button class="secondary" id="reset-model">Reset practice values</button></section>${quiz('steady','Quick check: what does steady state require?',['The total number of trees stays constant, even if class totals change.','Each class has the same stock before consecutive cutting cycles.','No trees are harvested.'],1,'All four class-by-class equalities must hold. A constant overall total alone is not enough.')}`,
()=>`${heading(2,'Build a transparent model.','Start with a new workbook. Use this cell layout so your equations, Solver settings, and sensitivity reports can be checked together.')}<div class="callout"><strong>Use the handout’s bounds:</strong> Problem 1 requires at least <strong>5 m³/ha per five-year cycle</strong>; Problem 2 requires at least <strong>5 large trees/ha</strong>. If you use an existing course workbook, reset Solver and rebuild the settings below. Previously saved settings or reports may describe a different scenario.</div><ol class="step-list"><li>Save a new <code>.xlsx</code> workbook and name the first sheet <code>max_large_trees</code>.</li><li>Enter the labels, starting values, and volume coefficients shown below. Stock and harvest are eight adjustable cells, not fixed inputs.</li><li>Enter each formula in its designated cell. Do not drag D5 down: every class has a different growth equation.</li><li>Format calculated values to show a few decimals, while retaining Excel’s full precision.</li></ol><div class="table-wrap"><table><thead><tr><th>Cells</th><th>Enter</th><th>Purpose</th></tr></thead><tbody><tr><td>A3, B3, D3</td><td>Size class; Stock at t; Stock at t+1</td><td>Stock headers (trees/ha)</td></tr><tr><td>A5:A8</td><td>1, 2, 3, 4 down the rows</td><td>Size classes</td></tr><tr><td>B5:B8</td><td>0 in each cell</td><td>Starting stock guesses; Solver changes these</td></tr><tr><td>A10, B10, C10</td><td>Size class; Harvest; Volume/tree</td><td>Harvest headers</td></tr><tr><td>A12:A15</td><td>1, 2, 3, 4 down the rows</td><td>Size classes</td></tr><tr><td>B12:B15</td><td>0 in each cell</td><td>Starting harvest guesses; Solver changes these</td></tr><tr><td>C12:C15</td><td>0.1, 0.5, 1.5, 3.0 down the rows</td><td>m³ per tree, by class</td></tr><tr><td>E7, B16</td><td>Large trees/ha; Harvest m³/ha/5 years</td><td>Output labels</td></tr></tbody></table></div><h2>Six formulas connect the model</h2><div class="table-wrap"><table><thead><tr><th>Cell</th><th>Excel formula</th><th></th></tr></thead><tbody>${formulas.map(([cell,f,label])=>`<tr><td><strong>${cell}</strong><br><small>${label}</small></td><td class="formula">${esc(f)}</td><td><button class="copy" data-copy="${esc(f)}" aria-label="Copy formula for ${cell}">Copy</button></td></tr>`).join('')}</tbody></table></div><p id="copy-status" class="small" aria-live="polite"></p><p class="small">If Excel uses semicolons as argument separators, use <code>=SUMPRODUCT(B12:B15;C12:C15)</code>. Units are labels next to the cells, not text typed into numeric cells.</p><h2>Check the wiring before solving</h2><p>With all eight decision cells at zero, D5 should equal 100; D6:D8, E8, and C16 should equal 0. This is only a formula check—it is not a feasible steady state. Changing B12 alone from 0 to 1 should lower D5 by 0.61, lower D6 by 0.04, and increase C16 by 0.1. Then restore B12 to zero.</p><details><summary>Why are the next-period cells not decision variables?</summary><p>D5:D8 are formulas calculated from the eight decision cells. Constraining B5:B8 = D5:D8 enforces the four steady-state conditions without adding four more adjustable variables.</p></details>`,
()=>`${heading(3,'One forest. Two priorities.','Solve each problem on its own worksheet. Keep the growth equations and feasibility rules; change the objective and the minimum requirement.')}<div class="two-col"><section class="panel"><p class="eyebrow">PROBLEM 1 / 60 POINTS</p><h2>Retain large trees</h2><p>Maximize <strong>y₃,t+1 + y₄,t+1</strong>, measured in trees/ha, while producing at least 5 m³/ha each cycle.</p><p><code>max_large_trees</code></p></section><section class="panel"><p class="eyebrow">PROBLEM 2 / 40 POINTS</p><h2>Produce timber</h2><p>Maximize <strong>0.1h₁ + 0.5h₂ + 1.5h₃ + 3.0h₄</strong>, measured in m³/ha/5 years, while retaining at least 5 large trees/ha.</p><p><code>max_timber</code></p></section></div><h2>Problem 1: configure Solver</h2><p>Open <strong>Data → Solver</strong> on <code>max_large_trees</code>. Enter these settings:</p><div class="table-wrap"><table><thead><tr><th>Solver setting</th><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td>Set Objective / To</td><td><code>$E$8</code> / <strong>Max</strong></td><td>Total large trees</td></tr><tr><td>By Changing Variable Cells</td><td><code>$B$5:$B$8,$B$12:$B$15</code></td><td>Four stocks + four harvests</td></tr><tr><td>Add constraint</td><td><code>$B$5:$B$8 = $D$5:$D$8</code></td><td>Steady state, equations (6)–(9)</td></tr><tr><td>Add constraint</td><td><code>$B$12:$B$15 &lt;= $B$5:$B$8</code></td><td>Harvest ≤ stock, equations (10)–(13)</td></tr><tr><td>Add constraint</td><td><code>$C$16 &gt;= 5</code></td><td>Timber minimum, equation (14)</td></tr><tr><td>Make Unconstrained Variables Non-Negative</td><td>Checked</td><td>All eight decision variables ≥ 0, equation (15)</td></tr><tr><td>Solving Method</td><td><strong>Simplex LP</strong></td><td>Continuous linear program; no integer constraints</td></tr></tbody></table></div><ol class="step-list"><li>Click <strong>Solve</strong>. Check that Solver reports an optimal solution and all constraints are satisfied.</li><li>Choose <strong>Keep Solver Solution</strong>. Select the <strong>Sensitivity</strong> report in the results dialog, then click OK.</li><li>Rename the generated report <code>report_large_trees</code>. Save the workbook before changing any settings.</li><li>Verify all four stock equalities, harvest ≤ stock, nonnegative decisions, and C16 ≥ 5. Decimal tree densities are allowed; do not round the decision cells to whole trees.</li></ol><h2>Problem 2: change the management goal</h2><ol class="step-list"><li>Duplicate <code>max_large_trees</code> and rename the copy <code>max_timber</code>. Keep the first problem’s sheet and report intact.</li><li>Open Solver on the copied sheet. Change the objective to <code>$C$16</code>, select <strong>Max</strong>, and keep the same eight changing cells.</li><li><strong>Delete</strong> the timber-minimum constraint <code>$C$16 &gt;= 5</code>. Add <code>$E$8 &gt;= 5</code> instead—this is the new constraint (16).</li><li>Keep both range constraints, nonnegativity, and Simplex LP. Confirm every reference points to this copied sheet.</li><li>Solve, keep the optimal solution, generate a new Sensitivity report, and rename it <code>report_timber</code>. Verify E8 ≥ 5 and all common feasibility conditions.</li></ol><div class="callout">The number 5 appears in both problems, but its unit changes. In Problem 1 it is a <strong>timber-production floor</strong>; in Problem 2 it is a <strong>large-tree retention floor</strong>.</div>${quiz('switch','Quick check: what changes in Problem 2?',['Only the name of the worksheet.','The objective becomes C16; C16 ≥ 5 is replaced by E8 ≥ 5.','Maximize E8 and require C16 ≤ 5.'],1,'Problem 2 maximizes timber production while requiring at least five large trees per hectare. The growth, steady-state, harvest, and nonnegativity rules stay in place.')}<details><summary>Solver or Sensitivity report is missing</summary><p>Enable the Solver add-in using the Microsoft instructions linked on the first step. Use desktop Excel for this workflow. For a Sensitivity report, solve the continuous model with Simplex LP and no integer or binary constraints. Confirm Solver found an optimum; then select Sensitivity in the results dialog. If you already closed that dialog, solve again.</p></details><details><summary>Solver finds no feasible solution or unexpected results</summary><p>Check the signs in D5, the +100 term, all four stock equalities, the direction of harvest ≤ stock, and the correct minimum for the current problem. Check that formulas remain formulas and only B5:B8 and B12:B15 are adjustable. Remove stale or broken references from Solver, then re-enter this step’s settings.</p></details><p class="small">Software guidance: <a href="https://support.microsoft.com/en-us/excel/define-and-solve-a-problem-by-using-solver" target="_blank" rel="noopener">Microsoft Solver instructions</a> · <a href="https://www.solver.com/excel-solver-create-solver-reports" target="_blank" rel="noopener">Frontline: creating Solver reports</a>.</p>`,
()=>`${heading(4,'Put the trade-off into words.','A shadow price measures the change in the optimal objective when a constraint’s right-hand side increases by one unit, within its allowable range. It is not necessarily a dollar price.')}<h2>Find the right row</h2><div class="table-wrap"><table><thead><tr><th>Report</th><th>Constraint row</th><th>Shadow-price units</th></tr></thead><tbody><tr><td><code>report_large_trees</code></td><td><code>$C$16</code>, timber minimum of 5</td><td>trees/ha per (m³/ha/5 years)</td></tr><tr><td><code>report_timber</code></td><td><code>$E$8</code>, large-tree minimum of 5</td><td>(m³/ha/5 years) per (tree/ha)</td></tr></tbody></table></div><p>Use the <strong>Constraints</strong> section, not the Variable Cells section’s reduced costs. Read the shadow price, constraint RHS, allowable increase, and allowable decrease from the report generated for that problem.</p><div class="equations"><div>Change in optimal objective = shadow price × change in RHS</div><div>Valid RHS interval = [RHS − allowable decrease, RHS + allowable increase]</div></div><p>A negative shadow price means increasing that minimum reduces the best attainable objective. The estimate assumes this is the only RHS change and all other model data stay fixed. Outside the allowable interval, re-solve the model.</p><section class="panel"><h2>Try your report values</h2><p class="small">Enter your own values; this calculator does not supply the assignment’s answers. The constraint RHS starts at 5 in both problems.</p><label for="price-mode">Which problem?</label><select id="price-mode"><option value="trees">1 · Maximize large trees</option><option value="timber">2 · Maximize timber</option></select><div class="note-grid" style="margin-top:16px"><label>Shadow price<input id="price" type="number" step="any" placeholder="From your report"></label><label>Change in RHS (new − 5)<input id="delta" type="number" step="any" value="1"></label><label>Allowable increase<input id="increase" type="number" min="0" step="any" placeholder="From your report"></label><label>Allowable decrease<input id="decrease" type="number" min="0" step="any" placeholder="From your report"></label></div><button id="calculate-price" style="margin-top:18px">Interpret this change</button><div id="price-feedback" class="feedback" aria-live="polite"></div></section><h2>Write your two explanations</h2><p class="small">Use the sign, magnitude, units, and allowable range from your reports. Copy these drafts into the appropriate Excel sheets before submitting. Drafts save locally; the calculator inputs above do not.</p><label for="note-0"><strong>Problem 1 · Timber minimum</strong></label><textarea id="note-0" data-note="0" placeholder="If the minimum timber production rises by 1 m³/ha per five-year cycle, the optimal number of large trees…"></textarea><label for="note-1" style="margin-top:20px"><strong>Problem 2 · Large-tree minimum</strong></label><textarea id="note-1" data-note="1" placeholder="If the minimum large-tree stock rises by 1 tree/ha, the optimal timber harvest per five-year cycle…"></textarea><div class="actions"><button id="export-notes" class="secondary">Download my notes ↓</button></div>${quiz('shadow','Quick check: what does a negative shadow price mean here?',['The model is infeasible.','Tightening the minimum reduces the optimal objective within the allowable range.','The same trade-off holds for any size change to the minimum.'],1,'The shadow price is a local marginal trade-off. Check the allowable increase and decrease before applying it; re-solve outside that interval.')}`,
()=>`${heading(5,'Ready to hand in.','Submit one Excel workbook containing both solved models, both Sensitivity reports, and your two written interpretations. The website is a learning guide, not the submission system.')}<div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Worksheet / location</th><th>Points</th></tr></thead><tbody><tr><td>Problem 1: formulate and solve equations (1)–(15)</td><td><code>max_large_trees</code></td><td>40</td></tr><tr><td>Problem 1: Sensitivity report</td><td><code>report_large_trees</code></td><td>15</td></tr><tr><td>Explain constraint (14)’s shadow price</td><td>Inside the workbook</td><td>5</td></tr><tr><td>Problem 2: revised objective and constraint (16)</td><td><code>max_timber</code></td><td>20</td></tr><tr><td>Problem 2: Sensitivity report</td><td><code>report_timber</code></td><td>15</td></tr><tr><td>Explain constraint (16)’s shadow price</td><td>Inside the workbook</td><td>5</td></tr></tbody></table></div><section class="panel checklist"><h2>Final workbook check</h2>${['My workbook contains all four sheets with the required names.','Both model sheets retain formulas, labels, and units.','Each solution meets all four steady-state equalities and harvest limits.','All stock and harvest decisions are nonnegative; I did not impose integers.','Problem 1 maximizes E8 with C16 ≥ 5 m³/ha/5 years.','Problem 2 maximizes C16 with E8 ≥ 5 trees/ha, and the old timber floor is removed.','Both reports were generated from the final matching solutions.','Both shadow-price explanations are in Excel and include direction, magnitude, units, and allowable-range context.'].map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks.includes(i)?'checked':''}>${s}</label>`).join('')}<p id="check-feedback" class="feedback" aria-live="polite"></p></section><h2>Save, reopen, submit</h2><ol><li>Save your final workbook as <code>.xlsx</code>.</li><li>Reopen it to confirm the four sheets and your explanations are present.</li><li>Submit the file through the location specified by your instructor. Check the course site for the deadline.</li></ol><div class="callout">Checking boxes here does not verify or submit your Excel file. If you cannot run Solver, contact your instructor for access instructions and include the step or error where you got stuck.</div><h2>Materials used</h2><p class="small">Assignment requirements, coefficients, points, and sheet names follow <a href="downloads/Lab7_Uneven_Aged.docx" download>Lab7_Uneven_Aged.docx</a> from the 2025 Lab7UEA materials. The Excel walkthrough uses the cell layout in UEM.xlsx. The supplied workbook contains prior scenario values and a report, so this guide teaches a fresh setup. The web activities are supplemental practice; the Excel workbook remains the required submission.</p>`
];
let current=0;
function render(){const slug=location.hash.slice(1);current=Math.max(0,steps.findIndex(s=>s[0]===slug));document.querySelector('#main').innerHTML=pages[current]();document.querySelector('#navigation').innerHTML=steps.map(([id,label],i)=>`<a href="#${id}" ${i===current?'class="active" aria-current="step"':''}><span class="step-number">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${label}</a>`).join('');document.querySelector('#complete').checked=state.done.includes(current);document.querySelector('#previous').disabled=current===0;document.querySelector('#next').disabled=current===5;document.querySelector('#progress').value=state.done.length;document.querySelector('#progress-text').textContent=`${state.done.length} of 6 steps complete`;document.querySelector('#percent').textContent=`${Math.round(state.done.length/6*100)}%`;if(current===1)updateModel();if(current===4)for(let i=0;i<2;i++)document.querySelector(`#note-${i}`).value=state.notes[i];if(current===5)updateChecklist();save();}
function project(y,h){const r=y.map((v,i)=>v-h[i]);return [100+.61*r[0]-.4*r[1]-1.4*r[2]-2.4*r[3],.04*r[0]+.8*r[1],.06*r[1]+.8*r[2],.04*r[2]+.9*r[3]];}
function updateModel(){const stockInputs=[...document.querySelectorAll('[data-stock]')],harvestInputs=[...document.querySelectorAll('[data-harvest]')];const inputs=[...stockInputs,...harvestInputs];const valid=inputs.every(el=>el.value.trim()!==''&&Number.isFinite(el.valueAsNumber)&&el.valueAsNumber>=0&&el.valueAsNumber<=1e9);for(const el of inputs)el.setAttribute('aria-invalid',String(!el.value.trim()||!Number.isFinite(el.valueAsNumber)||el.valueAsNumber<0||el.valueAsNumber>1e9));const feedback=document.querySelector('#model-feedback');if(!valid){feedback.className='feedback bad';feedback.textContent='Enter a finite, nonnegative number in every cell (up to 1 billion for this practice display).';for(const id of ['large-output','harvest-output','drift-output'])document.getElementById(id).textContent='—';for(let i=0;i<4;i++){document.getElementById(`projection-${i}`).textContent='—';document.getElementById(`change-${i}`).textContent='—';}document.querySelector('#chart').innerHTML='';return;}state.stock=stockInputs.map(el=>el.valueAsNumber);state.harvest=harvestInputs.map(el=>el.valueAsNumber);save();const y=state.stock,h=state.harvest,p=project(y,h),v=h.reduce((s,x,i)=>s+x*[.1,.5,1.5,3][i],0),large=p[2]+p[3],drift=Math.max(...p.map((n,i)=>Math.abs(n-y[i])));for(let i=0;i<4;i++){document.getElementById(`projection-${i}`).textContent=p[i].toFixed(3);document.getElementById(`change-${i}`).textContent=(p[i]-y[i]).toFixed(3);}document.querySelector('#large-output').textContent=large.toFixed(3);document.querySelector('#harvest-output').textContent=v.toFixed(3);document.querySelector('#drift-output').textContent=drift.toFixed(3);const problems=[];if(h.some((n,i)=>n>y[i]+1e-6))problems.push('Harvest exceeds stock in at least one class.');if(p.some(n=>n< -1e-6))problems.push('A projected stock is negative.');if(drift>.001)problems.push('Not at steady state: at least one class changes by more than 0.001 trees/ha.');feedback.className='feedback '+(problems.length?'bad':'good');feedback.textContent=(problems.join(' ')||'Common feasibility checks pass within a 0.001 trees/ha display tolerance; this does not establish optimality.')+` Problem 1 timber floor: ${v>=5-1e-6?'met':'not met'}. Problem 2 large-tree floor: ${large>=5-1e-6?'met':'not met'}.`;drawChart(y,p);}
function drawChart(y,p){const max=Math.max(1,...y,...p.map(Math.abs)),base=185,scale=145/max;let s=`<text x="24" y="18" font-size="12" fill="#627269">Trees/ha · shared scale 0–${max.toFixed(1)}</text><line x1="24" x2="625" y1="185" y2="185" stroke="#b8c5b5"/>`;for(let i=0;i<4;i++){const x=65+i*150;s+=`<rect x="${x}" y="${base-y[i]*scale}" width="32" height="${y[i]*scale}" fill="#244f3e"/><rect x="${x+38}" y="${base-Math.max(0,p[i])*scale}" width="32" height="${Math.max(0,p[i])*scale}" fill="${p[i]<0?'#9c3e27':'#c5a464'}"/><text x="${x+35}" y="225" text-anchor="middle" font-size="13" fill="#243c34">Class ${i+1}</text>`;}if(p.some(n=>n<0))s+='<text x="24" y="35" font-size="11" fill="#9c3e27">Negative projections are invalid; see table values.</text>';document.querySelector('#chart').innerHTML=s;}
function updateChecklist(){document.querySelector('#check-feedback').textContent=`${state.checks.length} of 8 checks marked. ${state.checks.length===8?'Review your saved workbook, then submit through your course site.':'Complete the remaining checks in Excel.'}`;}
function calculatePrice(){const ids=['price','delta','increase','decrease'],els=ids.map(id=>document.getElementById(id)),out=document.querySelector('#price-feedback');out.className='feedback bad';if(els.some(e=>e.value.trim()===''||!Number.isFinite(e.valueAsNumber))){out.textContent='Enter all four numeric values from your report and proposed change.';return;}const [price,delta,inc,dec]=els.map(e=>e.valueAsNumber);if(inc<0||dec<0){out.textContent='Allowable increase and decrease must be nonnegative.';return;}if(5+delta<0){out.textContent='Use a nonnegative minimum requirement for this lab.';return;}if(delta>inc||delta< -dec){out.textContent=`The new RHS (${(5+delta).toFixed(3)}) is outside the reported allowable interval [${(5-dec).toFixed(3)}, ${(5+inc).toFixed(3)}]. Re-solve; do not extrapolate this shadow price.`;return;}const change=price*delta;if(!Number.isFinite(change)){out.textContent='These values exceed the calculator range. Check the inputs.';return;}const unit=document.querySelector('#price-mode').value==='trees'?'trees/ha':'m³/ha per five-year cycle';out.className='feedback good';out.textContent=`Within the reported range, changing the minimum from 5 to ${(5+delta).toFixed(3)} changes the optimal objective by ${change.toFixed(3)} ${unit} (${change<0?'a decrease':change>0?'an increase':'no change'}), with other model data fixed. This is a change, not the new total objective.`;}
function exportNotes(){const text=`F422 Lab 7 — My reflection notes\n\nProblem 1: constraint (14)\n${state.notes[0]}\n\nProblem 2: constraint (16)\n${state.notes[1]}\n\nCopy these explanations into your Excel workbook. This export is not a lab submission.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Lab7-my-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.check-answer')){const q=b.closest('.quiz'),selected=q.querySelector('input:checked'),f=q.querySelector('.feedback');f.className='feedback '+(selected&&selected.value===q.dataset.answer?'good':'bad');f.textContent=!selected?'Choose an answer first.':selected.value===q.dataset.answer?'Correct. '+q.dataset.explanation:'Try again. '+q.dataset.explanation;}if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>{if(b.isConnected)b.textContent='Copy';},1600);}catch{document.querySelector('#copy-status').textContent='Clipboard access is unavailable. Select the formula text in the table and copy it manually.';}}if(b.id==='reset-model'){state.stock=[120,20,6,2];state.harvest=[20,0,0,0];render();}if(b.id==='calculate-price')calculatePrice();if(b.id==='export-notes')exportNotes();});
document.addEventListener('input',e=>{if(e.target.matches('[data-stock],[data-harvest]'))updateModel();if(e.target.matches('[data-note]')){state.notes[+e.target.dataset.note]=e.target.value;save();}if(['price','delta','increase','decrease','price-mode'].includes(e.target.id))document.querySelector('#price-feedback').textContent='';});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){const i=+e.target.dataset.check;state.checks=state.checks.filter(x=>x!==i);if(e.target.checked)state.checks.push(i);save();updateChecklist();}});
document.querySelector('#complete').addEventListener('change',e=>{state.done=state.done.filter(x=>x!==current);if(e.target.checked)state.done.push(current);save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);});
document.querySelector('#previous').addEventListener('click',()=>{if(current>0)location.hash=steps[current-1][0];});document.querySelector('#next').addEventListener('click',()=>{if(current<5)location.hash=steps[current+1][0];});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});});
document.querySelector('#print').addEventListener('click',()=>{const main=document.querySelector('#main');main.innerHTML=pages.map((p,i)=>`<section class="print-section" data-print-step="${i}">${p()}</section>`).join('');for(let i=0;i<2;i++)document.querySelector(`#note-${i}`).value=state.notes[i];updateModel();updateChecklist();window.print();render();});
render();
